-- Dados de exemplo do SafeIncident (para testar dashboard, lista e relatórios).
-- Execute no phpMyAdmin com o banco 'safeincident' selecionado, DEPOIS de criar o usuário de login.
-- As datas são relativas a hoje, então os gráficos sempre ficam com dados dos últimos meses.
-- Os 3 últimos registros têm 'excluido_em' preenchido: provam que a exclusão lógica funciona.
SET NAMES utf8mb4;
USE safeincident;

SET @usuario := (SELECT MIN(id_usuario) FROM usuarios);
SET @phishing := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Phishing');
SET @malware := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Malware');
SET @ransomware := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Ransomware');
SET @engsocial := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Engenharia Social');
SET @acesso := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Acesso Não Autorizado');
SET @vazamento := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Vazamento de Dados');
SET @outro := (SELECT id_tipo FROM tipos_ataque WHERE nome = 'Outro');

